INSERT INTO `contents` VALUES (5,'SMsJr1','What our Customer says!','Don\'t take our word for it, here\'s what some of our clients have to say about us','2020-08-22 11:13:00','2021-10-27 09:59:35'),(11,'anvs8c','About Us','About us header','2020-08-22 11:32:29','2021-10-27 10:21:22'),(12,'epJ4LI','Who we are','online trade \r\n                            is a solution for creating an investment management platform. It is suited for\r\n                            hedge or mutual fund managers and also Forex, stocks, bonds and cryptocurrency traders who\r\n                            are looking at runing pool trading system. Onlinetrader simplifies the investment,\r\n                            monitoring and management process. With a secure and compelling mobile-first design,\r\n                            together with a default front-end design, it takes few minutes to setup your own investment\r\n                            management or pool trading platform.','2020-08-22 11:33:32','2021-10-27 10:24:01'),(13,'5hbB6X','Get Started','How to get started ?','2020-08-22 11:33:55','2021-10-27 10:25:09'),(14,'Zrhm3I','Create an Account','Create an account with us using your preffered email/username','2020-08-22 11:34:11','2021-10-27 10:25:29'),(15,'yTKhlt','Make a Deposit','Make A deposit with any of your preffered currency','2020-08-22 11:34:26','2021-10-27 10:25:52'),(16,'u0Ervr','Start Trading/Investing','Start trading with Indices commodities e.tc','2020-08-22 11:34:56','2021-10-27 10:26:12'),(23,'vr6Xw0','Our Investment Packages','Choose how you want to invest with us','2020-08-22 11:37:43','2021-10-27 09:58:51'),(30,'52GPRA','Address','No 10 Mission Road, Nigeria','2020-08-22 11:40:19','2020-08-22 11:40:19'),(31,'0EXbji','Phone Number','+234 9xxxxxxxx','2020-08-22 11:40:36','2020-09-14 10:13:57'),(32,'HLgyaQ','Email','support@brynamics.xyz','2020-08-22 11:41:14','2020-08-22 12:23:55'),(35,'Mnag31','The Better Way to Trade & Invest','Online Trade helps over 2 million customers achieve their financial goals by helping them trade and invest with ease','2021-10-27 09:42:23','2022-11-10 18:42:38'),(36,'rXJ7JQ','Trade Invest stock, and Bond','Home page text','2021-10-27 09:45:17','2021-10-27 09:45:17'),(37,'J23T0Y','Security Comes First','Security Comes first','2021-10-27 09:53:15','2021-10-27 09:54:52'),(38,'9HOR1z','Security','Online Trade uses the highest levels of Internet Security, and it is secured by 256 bits SSL security encryption to ensure that your information is completely protected from fraud.','2021-10-27 09:56:13','2021-10-27 09:56:13'),(39,'7DH2G9','Two Factor Auth','Two-factor authentication (2FA) by default on all Online Trade accounts, to securely protect you from unauthorised access and impersonation.','2021-10-27 09:56:26','2021-10-27 09:56:26'),(40,'5Vg32I','Explore Our Services','It’s our mission to provide you with a delightful and a successful trading experience!','2021-10-27 09:56:38','2021-10-27 09:56:38'),(41,'Vg6Gy7','Powerful Trading Platforms','Online Trade offers multiple platform options to cover the needs of each type of trader and investors .','2021-10-27 09:56:53','2021-10-27 09:56:53'),(42,'1Sx1dl','High leverage','Chance to magnify your investment and really win big with super-low spreads to further up your profits','2021-10-27 09:57:06','2021-10-27 09:57:06'),(43,'YYqKx3','Fast execution','Super-fast trading software, so you never suffer slippage.','2021-10-27 09:57:20','2021-10-27 09:57:20'),(44,'yGg8xI','Ultimate Security','With advanced security systems, we keep your account always protected.','2021-10-27 09:57:35','2021-10-27 09:57:35'),(45,'xEWMho','24/7 live chat Support','Connect with our 24/7 support and Market Analyst on-demand.','2021-10-27 09:57:48','2021-10-27 09:57:48'),(46,'9SOtK1','Always on the go? Mobile trading is easier than ever with Online Trade!','Get your hands on our customized Trading Platform with the comfort of freely trading on the move, to experience truly liberating trading sessions.','2021-10-27 09:58:05','2021-10-27 09:58:05'),(47,'wOS1ve','Cryptocurrency','Trade and invest Top Cryptocurrency','2021-10-27 09:59:07','2021-10-27 09:59:07'),(48,'wuZlis','Hello!, How can we help you?','Hello!, How can we help you?','2021-10-27 10:32:12','2021-10-27 10:32:12'),(49,'1TYkw0','Find the help you need','Launch your campaign and benefit from our expertise on designing and managing conversion centered bootstrap4 html page.','2021-10-27 10:32:33','2021-10-27 10:32:33'),(50,'rK6Yhn','FAQs','Due to its widespread use as filler text for layouts, non-readability is of great importance.','2021-10-27 10:32:49','2021-10-27 10:32:49'),(51,'HBHBLo','Guides / Support','Due to its widespread use as filler text for layouts, non-readability is of great importance.','2021-10-27 10:33:03','2021-10-27 10:33:03'),(52,'rCTDQh','Support Request','Due to its widespread use as filler text for layouts, non-readability is of great importance.','2021-10-27 10:33:14','2021-10-27 10:33:14'),(53,'kMsswR','Get Started','Launch your campaign and benefit from our expertise on designing and managing conversion centered bootstrap4 html page.','2021-10-27 10:33:28','2021-10-27 10:33:28'),(54,'EOUU7R','Get in Touch !','This is required when, for text is not yet available.','2021-10-27 10:33:56','2021-10-27 10:33:56'),(56,'ROu4q6','Contact Us','Contact Us','2021-10-27 10:47:41','2021-10-27 10:47:41');
