INSERT INTO `trading_bots` VALUES (1,'ForexMaster Pro','forex','Advanced forex trading bot specializing in major currency pairs. Uses sophisticated algorithms to analyze market trends and execute profitable trades with high precision. Perfect for conservative investors seeking steady returns.',NULL,100.00,10000.00,0.80,2.50,87,30,0.00,0,'inactive','[\"EUR\\/USD\",\"GBP\\/USD\",\"USD\\/JPY\",\"USD\\/CHF\",\"AUD\\/USD\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}',NULL,'2025-07-23 10:38:10','2026-01-13 00:15:03'),(2,'TIER 3','crypto','High-performance cryptocurrency trading bot designed for the volatile crypto markets. Leverages machine learning to identify optimal entry and exit points across major cryptocurrencies.',NULL,2000.00,250000.00,6.00,7.00,88,30,22.96,2,'active','[\"BTC\\/USD\",\"ETH\\/USD\",\"BNB\\/USD\",\"ADA\\/USD\",\"SOL\\/USD\",\"DOT\\/USD\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}','2026-01-17 01:16:02','2025-07-23 10:38:10','2026-01-17 17:43:00'),(4,'TIER 4','commodities','Specialized commodities trading bot with expertise in precious metals and energy markets. Ideal for portfolio diversification and inflation hedging strategies.',NULL,4000.00,150000.00,7.00,11.00,84,30,17916.36,4,'active','[\"GOLD\",\"SILVER\",\"OIL\",\"COPPER\",\"NATURAL_GAS\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}','2026-01-30 08:06:01','2025-07-23 10:38:10','2026-01-30 08:06:01'),(5,'IndexMaster Pro','indices','Advanced index trading bot that capitalizes on major market indices movements. Uses correlation analysis and macro-economic indicators for strategic positioning.',NULL,300.00,20000.00,0.60,2.20,86,75,0.00,0,'inactive','[\"S&P500\",\"NASDAQ\",\"DOW\",\"FTSE\",\"DAX\",\"NIKKEI\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}',NULL,'2025-07-23 10:38:10','2026-01-13 00:14:29'),(6,'ScalpMaster Quick','forex','High-frequency scalping bot designed for quick profits from small price movements. Perfect for active traders seeking multiple daily opportunities with controlled risk.',NULL,150.00,5000.00,1.50,3.50,79,21,82.81,2,'inactive','[\"EUR\\/USD\",\"GBP\\/JPY\",\"USD\\/CAD\",\"AUD\\/NZD\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}','2025-08-09 09:10:03','2025-07-23 10:38:10','2026-01-13 00:13:01'),(7,'TIER 2','crypto','SmartBot: Automated trading bot for crypto & forex markets.',NULL,700.00,20000.00,5.20,7.00,90,30,46.48,1,'active','[\"Euro\\/USD\",\"BTC\\/USD\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}','2026-01-17 01:16:04','2025-07-23 11:15:03','2026-01-17 17:43:24'),(8,'TIER 1','crypto','Next-generation algorithmic trading bot powered by quantum computing principles. Specializes in high-frequency crypto arbitrage across multiple exchanges with lightning-fast execution.',NULL,100.00,100000.00,3.50,5.00,91,30,9993242886351.20,4,'active','[\"BTC\\/USDT\",\"ETH\\/USDT\",\"BNB\\/USDT\",\"ADA\\/USDT\",\"SOL\\/USDT\",\"AVAX\\/USDT\"]','{\"stop_loss\":5,\"take_profit\":10,\"max_trades_per_day\":5,\"risk_per_trade\":2}','{\"algorithm\":\"Advanced AI Algorithm\",\"indicators\":[\"RSI\",\"MACD\",\"Moving Averages\"],\"timeframe\":\"1H\",\"market_analysis\":\"Technical & Fundamental\"}','2026-08-10 22:36:01','2025-07-23 11:24:53','2026-08-10 22:36:01');
